using Town.Core;
using System.Text.Json.Nodes;
if(args.Contains("--map"))
{
    var w=World.Create(424242);
    Console.WriteLine("legend: . water  s sand  - grass  = soil  o/O/* rock");
    for(int z=-32;z<=0;z+=4){var l2=new System.Text.StringBuilder();for(int x=-40;x<=-20;x+=2)l2.Append($"{w.Height(x,z),3}");Console.WriteLine($"H{z,4} {l2}");}
    for(int z=-World.Half;z<World.Half;z+=1)
    {
        var line=new System.Text.StringBuilder();
        for(int x=-World.Half;x<World.Half;x+=1)
        {
            int h=w.Height(x,z);
            var sf=w.Surface(x,z);
            char c=h==0?'.':sf==GroundSurface.Sand?'s':sf==GroundSurface.Soil?'=':sf==GroundSurface.Stone?(h>=40?'*':h>=20?'O':'o'):'-';
            line.Append(c);
        }
        Console.WriteLine($"{z,4} {line}");
    }
    return;
}
if(args.Contains("--stats"))
{
    foreach(int seed in args.Where(a=>int.TryParse(a,out _)).Select(int.Parse).DefaultIfEmpty(424242))
    {
        var w=World.Create(seed);
        int land=w.Heights.Count(h=>h>0),high=w.Heights.Count(h=>h>=14),mid=w.Heights.Count(h=>h is >=3 and <=8);
        Console.WriteLine($"seed {seed}: land {land} ({land/(double)(World.Size*World.Size):P1}) max {w.Heights.Max()} >=14 {high} 3-8 {mid} trees {w.Nature.Count} terracing {string.Join(',',w.Heights.GroupBy(h=>h).OrderBy(g=>g.Key).Select(g=>$"{g.Key}:{g.Count()}"))}");
    }
    return;
}
int passed=0;
void Check(bool value,string message){if(!value)throw new Exception(message);}
void Test(string name,Action action){action();passed++;Console.WriteLine($"PASS {name}");}
Cell Free(World world,string kind="oven",int rotation=1){for(int z=16;z>=-20;z--)for(int x=20;x>=-20;x--)if(world.CanPlace(kind,x,z,rotation).Ok)return new(x,z);throw new Exception("No free cell");}
Test("deterministic world and all starter footprints",()=>{var a=World.Create(424242);Check(SaveCodec.Encode(a)==SaveCodec.Encode(World.Create(424242)),"world diverged");foreach(var o in a.Objects)Check(World.Catalog.ContainsKey(o.Kind),o.Kind);});
Test("place, occupancy and invalid commands are atomic",()=>{var w=World.Create(424242);var p=Free(w,"boat");Check(w.Execute(new("place",p.X,p.Z,"boat",1)).Ok,"place");Check(w.Occupant(p.X+1,p.Z)?.Kind=="boat","rotated occupancy");string saved=SaveCodec.Encode(w);foreach(var c in new[]{new WorldCommand("place",p.X,p.Z,"oven",1),new("place",int.MaxValue,int.MinValue,"oven",0),new("place",0,0,"unknown",0),new("raise",-40,-40)}){Check(!w.Execute(c).Ok,"invalid accepted");Check(SaveCodec.Encode(w)==saved,"invalid mutated");}});
Test("move preserves identity and updates grid atomically",()=>{var w=World.Create(424242);var item=w.Objects.First(o=>o.Kind=="house");var p=Free(w,"house");Check(w.Execute(new("move",p.X,p.Z,Rotation:1,ObjectId:item.Id)).Ok,"move");Check(w.Occupant(p.X+1,p.Z)?.Id==item.Id,"identity lost");Check(w.Occupant(item.X,item.Z)==null,"old cells occupied");var before=SaveCodec.Encode(w);Check(!w.Execute(new("move",10,0,Rotation:0,ObjectId:item.Id)).Ok,"overlap accepted");Check(SaveCodec.Encode(w)==before,"failed move mutated");});
Test("layer edits, neighboring chunks and tree protection",()=>{var w=World.Create(424242);var p=Free(w,"road",0);int h=w.Height(p.X,p.Z);Check(w.Execute(new("raise",p.X,p.Z)).Ok,"raise");Check(w.Height(p.X,p.Z)==h+1,"not layered");Check(!w.Execute(new("raise",0,0)).Ok,"building not protected");var n=w.Nature[0];Check(!w.Execute(new("lower",n.X,n.Z)).Ok,"tree not protected");Check(WorldQueries.AffectedChunks([new(-World.Half+WorldQueries.ChunkSize,-World.Half+WorldQueries.ChunkSize)]).Count==3,"chunk border invalidation");Check(WorldQueries.ChunkCount==144,"chunk count");});
Test("save roundtrip and malformed data preservation",()=>{var w=World.Create(424242);var p=Free(w);w.Execute(new("place",p.X,p.Z,"oven",1));var text=SaveCodec.Encode(w);Check(SaveCodec.Encode(SaveCodec.Decode(text))==text,"roundtrip");foreach(var bad in new[]{"garbage","null","{}",text.Replace("\"schema\":4","\"schema\":3")}){bool rejected=false;try{SaveCodec.Decode(bad);}catch(FormatException){rejected=true;}Check(rejected,"malformed accepted");}});
Test("untrusted overlap and tree modifications reject",()=>{var baseline=SaveCodec.Encode(World.Create(424242));foreach(string mode in new[]{"overlap","surface","tree","id"}){var v=JsonNode.Parse(baseline)!.AsObject();if(mode=="surface")v["surfaces"]![0]=99;else if(mode=="tree"){var n=World.Create(424242).Nature[0];v["heights"]![World.Index(n.X,n.Z)]=0;}else if(mode=="id")v["objects"]![0]!["id"]=0;else{var clone=v["objects"]![0]!.DeepClone();clone["id"]=v["nextId"]!.GetValue<int>();v["nextId"]=v["nextId"]!.GetValue<int>()+1;v["objects"]!.AsArray().Add(clone);}bool rejected=false;try{SaveCodec.Decode(v.ToJsonString());}catch(FormatException){rejected=true;}Check(rejected,mode);}});
Test("fixed step, queued command, undo and changes",()=>{var sim=new Simulation();var p=Free(sim.World);sim.Enqueue(new("place",p.X,p.Z,"oven",1));int count=sim.World.Objects.Count;sim.Advance(.02);Check(sim.World.Objects.Count==count,"command applied outside tick");sim.Advance(.03);Check(sim.Ticks==1&&sim.World.Objects.Count==count+1,"tick command");Check(sim.TryChange(out var change)&&change.Type=="place","no render event");Check(sim.Undo()&&sim.World.Objects.Count==count,"undo");Check(sim.TryChange(out change)&&change.Type=="reload","undo not invalidated");long before=sim.Ticks;sim.Advance(100);Check(sim.Ticks-before<=5,"unbounded catchup");});

World WithStock(params (string Item,int Amount)[] values){var node=JsonNode.Parse(SaveCodec.Encode(World.Create(424242)))!;var stock=node["gameplay"]!["stock"]!.AsObject();stock.Clear();foreach(var (item,amount)in values)stock[item]=amount;return SaveCodec.Decode(node.ToJsonString());}
void Ok(World w,WorldCommand c){var r=w.Execute(c);Check(r.Ok,$"{c.Type}/{c.Kind}: {r.Message}");}
void AtomicReject(World w,WorldCommand c){string before=SaveCodec.Encode(w);Check(!w.Execute(c).Ok,"invalid accepted");Check(SaveCodec.Encode(w)==before,"failed operation changed state");}
void Advance(World w,int ticks,Action<World>? after=null){var sim=new Simulation();sim.Load(SaveCodec.Encode(w));for(int i=0;i<ticks/5;i++)sim.Advance(.25);after?.Invoke(sim.World);}
World PileWorld(string item,int quantity,out Cell tile){var w=WithStock((item,quantity));tile=Free(w,"house",0);Ok(w,new("stockDrop",tile.X,tile.Z,Item:item,Quantity:quantity,ExpectedStock:quantity));return w;}
Test("axe creates physical drops; only pickup changes stock",()=>{var w=WithStock();var t=w.LiveTrees.First();Ok(w,new("tool",t.X,t.Z,"axe"));Check(w.Drops.Count(d=>d.Item=="wood")==2&&w.Drops.Count(d=>d.Item=="treeSeed")==2,"wrong wood yield");Check(w.UsedStorage==0&&!w.LiveTrees.Contains(t),"automatic pickup or tree survived");foreach(var d in w.Drops.ToArray())Ok(w,new("pickup",0,0,SourceId:d.Id));Check(w.Stock("wood")==2&&w.Stock("treeSeed")==2&&w.Drops.Count==0,"pickup");Check(w.Discoveries.ContainsKey("gather-wood"),"not discovered");Check(SaveCodec.Encode(SaveCodec.Decode(SaveCodec.Encode(w)))==SaveCodec.Encode(w),"cleared tree restore");});
Test("full warehouse retains physical loot without loss",()=>{var w=WithStock(("wood",16));var t=w.LiveTrees.First();Ok(w,new("tool",t.X,t.Z,"axe"));AtomicReject(w,new("pickup",0,0,SourceId:w.Drops[0].Id));});
Test("all exact material tool recipes and discovery",()=>{foreach(var (tool,item,n,kind,recipe)in new[]{("hammer","wood",1,"orderBoard","build-order-board"),("hammer","wood",2,"crate","build-crate"),("hammer","wood",3,"woodenPier","build-wooden-pier"),("hammer","wood",4,"house","build-house"),("hammer","stone",2,"stoneMill","build-stone-mill"),("saw","wood",3,"handcart","build-handcart"),("saw","wood",4,"boat","build-boat")}){var w=PileWorld(item,n,out var p);var c=new WorldCommand("tool",p.X,p.Z,tool);string before=SaveCodec.Encode(w);Check(w.PreviewPlan(c).Ghost?.Kind==kind,"preview model");Check(before==SaveCodec.Encode(w),"preview consumed material");Ok(w,c);Check(w.Piles.Count==0&&w.Occupant(p.X,p.Z)?.Kind==kind&&w.Discoveries.ContainsKey(recipe),recipe);}});
Test("wrong amount and stale drag snapshot reject atomically",()=>{var w=PileWorld("wood",5,out var p);AtomicReject(w,new("tool",p.X,p.Z,"hammer"));AtomicReject(w,new("stockDrop",p.X+2,p.Z,Item:"wood",ExpectedStock:5));var old=w.Piles[0];Ok(w,new("pickup",0,0,SourceId:old.Id));AtomicReject(w,new("tool",p.X,p.Z,"hammer",Piles:[old]));});
Test("partial pile merge keeps overflow and IDs",()=>{var w=WithStock(("wood",9));var a=Free(w,"house",0);Ok(w,new("stockDrop",a.X,a.Z,Item:"wood",Quantity:5));var b=Free(w,"house",0);Ok(w,new("stockDrop",b.X,b.Z,Item:"wood",Quantity:4));var source=w.Piles.First(p=>p.X==b.X);Ok(w,new("movePile",a.X,a.Z,SourceId:source.Id,Piles:[source]));Check(w.Piles.Single(p=>p.X==a.X).Amount==6&&w.Piles.Single(p=>p.Id==source.Id).Amount==3,"overflow lost");});
Test("wood plus stone requires both explicit sources; remainder survives",()=>{var w=WithStock(("wood",2),("stone",2));var a=Free(w,"house",0);Ok(w,new("stockDrop",a.X,a.Z,Item:"wood",Quantity:2));var b=Free(w,"house",0);Ok(w,new("stockDrop",b.X,b.Z,Item:"stone",Quantity:2));var dest=Free(w);AtomicReject(w,new("tool",dest.X,dest.Z,"hammer"));Ok(w,new("tool",dest.X,dest.Z,"hammer",Piles:w.Piles.ToArray()));Check(w.Occupant(dest.X,dest.Z)?.Kind=="oven"&&w.Piles.Sum(p=>p.Amount)==2,"mixed craft");});
Test("entity combinations preserve base identity, location and farm crops",()=>{foreach(var (baseKind,extra,result,recipe)in new[]{("house","crate","warehouse","build-warehouse"),("house","orderBoard","shop","build-shop"),("house","stoneMill","mill","build-mill"),("house","oven","bakery","build-bakery"),("warehouse","handcart","transportWarehouse","build-transport-warehouse"),("farm","crate","farm","attach-farm-box")}){var w=World.Create(424242);var b=w.Objects.First(o=>o.Kind==baseKind);var p=Free(w,extra,0);Ok(w,new("place",p.X,p.Z,extra));var e=w.Objects[^1];var farm=w.Farm(b.Id);Ok(w,new("merge",0,0,Entities:[e,b]));Check(w.Objects.Single(o=>o.Id==b.Id)==b with{Kind=result},recipe);Check(!w.Objects.Any(o=>o.Id==e.Id)&&w.Discoveries.ContainsKey(recipe),"part not consumed");if(farm is not null)Check(w.Farm(b.Id)!.Box&&w.Farm(b.Id)!.Cells.SequenceEqual(farm.Cells),"farm state lost");}});
Test("watering gesture uses nine soil across selected piles",()=>{var w=WithStock(("soil",10));var a=Free(w,"house",0);Ok(w,new("stockDrop",a.X,a.Z,Item:"soil",Quantity:5));var b=Free(w,"house",0);Ok(w,new("stockDrop",b.X,b.Z,Item:"soil",Quantity:5));Ok(w,new("tool",b.X,b.Z,"wateringCan",Piles:w.Piles.ToArray()));Check(w.Piles.Single(p=>p.Item=="soil").Amount==1&&w.Piles.Single(p=>p.Item=="mud").Amount==1,"soil water remainder");});
Test("mud attached upgrades and warehouse expansion",()=>{foreach(var (kind,result,recipe)in new[]{("house","residence","build-residence"),("crate","nursery","build-nursery"),("warehouse","expandedWarehouse","expand-warehouse")}){var w=WithStock(("mud",1),("wood",2));var b=w.Objects.First(o=>o.Kind==kind);Ok(w,new("stockDrop",b.X,b.Z,Item:kind=="warehouse"?"wood":"mud",Quantity:1));if(kind=="warehouse")Ok(w,new("stockDrop",b.X,b.Z,Item:"wood"));Ok(w,new("tool",b.X,b.Z,"hammer",ObjectId:b.Id));Check(w.Objects.Single(o=>o.Id==b.Id).Kind==result&&w.Discoveries.ContainsKey(recipe),recipe);if(kind=="warehouse")Check(w.Capacity==32,"expansion capacity");}});
Test("crop harvest is per cell; plant and 15 second growth",()=>{var w=WithStock(("wheat",1));var f=w.Farms.First();var b=w.Objects.Single(b=>b.Id==f.Id);Ok(w,new("tool",b.X,b.Z,"sickle",ObjectId:b.Id,FarmCell:4));Check(w.Farm(b.Id)!.Cells.Count(c=>c is not null)==8&&w.Drops.Sum(d=>d.Amount)==2,"sickle affected neighbors");Ok(w,new("plant",b.X,b.Z,ObjectId:b.Id,Item:"wheat",FarmCell:4));AtomicReject(w,new("tool",b.X,b.Z,"sickle",ObjectId:b.Id,FarmCell:4));Advance(w,300,grown=>{Ok(grown,new("tool",b.X,b.Z,"sickle",ObjectId:b.Id,FarmCell:4));Check(grown.Drops.Count==4,"mature yield");});});
Test("empty farm irrigation and rice; farm box retains at capacity",()=>{var w=WithStock(("rice",1));var p=Free(w,"farm",0);Ok(w,new("tool",p.X,p.Z,"diggingTool"));var b=w.Occupant(p.X,p.Z)!;Ok(w,new("tool",p.X,p.Z,"wateringCan",ObjectId:b.Id));Ok(w,new("plant",p.X,p.Z,ObjectId:b.Id,Item:"rice",FarmCell:0));var crate=w.Objects.First(o=>o.Kind=="crate");Ok(w,new("merge",0,0,Entities:[b,crate]));Advance(w,300,grown=>{Ok(grown,new("tool",p.X,p.Z,"sickle",ObjectId:b.Id,FarmCell:0));Check(grown.Farm(b.Id)!.BoxStock!["rice"]==2&&grown.Drops.Count==0,"farm box");Ok(grown,new("collectBox",p.X,p.Z,ObjectId:b.Id));Check(grown.Stock("rice")==2&&grown.Discoveries.ContainsKey("grow-rice"),"box pickup");});});
Test("processing consumes once, waits, collects and survives save",()=>{foreach(var (recipe,rule)in World.Processing.Where(p=>p.Key!="make-fertilizer"&&p.Key!="grow-sapling")){var w=WithStock(rule.Inputs.Select(p=>(p.Item,p.Amount)).ToArray());var b=w.Objects.First(o=>o.Kind==rule.Building);Ok(w,new("process",b.X,b.Z,ObjectId:b.Id,Item:recipe));AtomicReject(w,new("process",b.X,b.Z,ObjectId:b.Id,Item:recipe));AtomicReject(w,new("collectJob",b.X,b.Z,ObjectId:b.Id));Advance(w,rule.Ticks,done=>{Ok(done,new("collectJob",b.X,b.Z,ObjectId:b.Id));Check(done.Jobs.Count==0&&rule.Outputs.All(p=>done.Stock(p.Item)==p.Amount)&&done.Discoveries.ContainsKey(recipe),recipe);});}});
Test("compost mixed inputs and nursery to planted tree lifecycle",()=>{var w=WithStock(("vegetable",1),("treeSeed",2),("mud",1));var c=w.Objects.First(o=>o.Kind=="crate");Ok(w,new("tool",c.X,c.Z,"hammer",ObjectId:c.Id));Ok(w,new("stockDrop",c.X,c.Z,Item:"vegetable"));Ok(w,new("stockDrop",c.X,c.Z,Item:"treeSeed"));Check(w.Jobs.Single().Recipe=="make-fertilizer","compost did not start");Advance(w,300,done=>{Ok(done,new("collectJob",c.X,c.Z,ObjectId:c.Id));Check(done.Stock("fertilizer")==1,"compost output");});var n=w.Objects.Last(o=>o.Kind=="crate");Ok(w,new("stockDrop",n.X,n.Z,Item:"mud"));Ok(w,new("tool",n.X,n.Z,"hammer",ObjectId:n.Id));Ok(w,new("stockDrop",n.X,n.Z,Item:"treeSeed"));Ok(w,new("tool",n.X,n.Z,"wateringCan",ObjectId:n.Id));Advance(w,300,done=>{Ok(done,new("collectJob",n.X,n.Z,ObjectId:n.Id));var p=Free(done);Ok(done,new("stockDrop",p.X,p.Z,Item:"sapling"));AtomicReject(done,new("tool",p.X,p.Z,"axe"));Advance(done,600,mature=>{Ok(mature,new("tool",p.X,p.Z,"axe"));Check(mature.Discoveries.ContainsKey("plant-sapling"),"tree cycle");});});});
Test("layer digging yields ground loot and fill consumes soil",()=>{var w=WithStock(("soil",1));var p=Free(w,"road",0);while(w.Height(p.X,p.Z)<2)Ok(w,new("raise",p.X,p.Z));int h=w.Height(p.X,p.Z);Ok(w,new("terrainDig",p.X,p.Z));Check(w.Height(p.X,p.Z)==h-1&&w.Drops.Count==1,"terrain yield");Ok(w,new("terrainFill",p.X,p.Z));Ok(w,new("pickup",0,0,SourceId:w.Drops[0].Id));Check(w.Height(p.X,p.Z)==h&&w.Stock("soil")==1,"fill consumption");});
Test("full farm box preserves the ninth crop and rejects oversized pickup",()=>{var w=World.Create(424242);var b=w.Objects.First(o=>o.Kind=="farm");var c=w.Objects.First(o=>o.Kind=="crate");Ok(w,new("merge",0,0,Entities:[b,c]));for(int i=0;i<8;i++)Ok(w,new("tool",b.X,b.Z,"sickle",ObjectId:b.Id,FarmCell:i));Check(w.Farm(b.Id)!.BoxStock!.Values.Sum()==16,"box capacity");AtomicReject(w,new("tool",b.X,b.Z,"sickle",ObjectId:b.Id,FarmCell:8));AtomicReject(w,new("collectBox",b.X,b.Z,ObjectId:b.Id));});
Test("null gameplay records reject safely",()=>{foreach(string name in new[]{"piles","drops","jobs","trees","farms","attachments"}){var n=JsonNode.Parse(SaveCodec.Encode(World.Create(424242)))!;n["gameplay"]![name]!.AsArray().Add((JsonNode?)null);bool rejected=false;try{SaveCodec.Decode(n.ToJsonString());}catch(FormatException){rejected=true;}Check(rejected,name);}});

Test("seeded islands are reproducible and contain the requested terrain",()=>{var maps=new HashSet<string>();for(int seed=1;seed<=24;seed++){var w=World.Create(seed);Check(w.Seed==seed,"seed metadata");Check(w.Heights.Max()>=20,$"mountain too low: {w.Heights.Max()}");Check(w.Heights.Count(h=>h>=14)>=40,"mountain massif too small");Check(w.Heights.Count(h=>h is >=3 and <=8)>=200,"foothills absent");Check(w.Nature.Count>=250,$"forest too small: {w.Nature.Count}");Check(w.Heights.Where((h,i)=>h==2&&w.Surfaces[i]==(byte)GroundSurface.Grass).Count()>=1200,"plain absent");Check(w.Objects.Count==47,"starting objects invalid");Check(w.Heights.Count(h=>h==0)>=1500,"island too small");var json=SaveCodec.Encode(w);Check(maps.Add(json),"duplicate island");Check(json==SaveCodec.Encode(World.Create(seed)),"seed not deterministic");Check(json==SaveCodec.Encode(SaveCodec.Decode(json)),"seed roundtrip");}Check(World.Create().Seed!=World.Create().Seed,"fresh islands reuse seed");});
Test("river reaches the sea and stays two cells wide",()=>{for(int seed=1;seed<=12;seed++){var w=World.Create(seed);int water=0;for(int z=-World.Half;z<World.Half;z++)for(int x=-World.Half;x<World.Half;x++)if(w.Height(x,z)==0)water++;int interior=0;for(int z=-World.Half+3;z<World.Half-3;z++)for(int x=-World.Half+3;x<World.Half-3;x++)if(w.Height(x,z)==0&&Enumerable.Range(-3,7).All(d=>w.Height(x+d,z)+w.Height(x,z+d)>0||true))interior++;Check(water>1500,"island shape");Check(InteriorWater(w)>0,$"no river seed {seed}");}});
int InteriorWater(World w){int count=0;for(int z=-World.Half+6;z<World.Half-6;z++)for(int x=-World.Half+6;x<World.Half-6;x++)if(w.Height(x,z)==0)count++;return count;}
Test("stone comes from the mountain and soil from open land",()=>{var w=WithStock();var rock=Enumerable.Range(-World.Half,World.Size).SelectMany(z=>Enumerable.Range(-World.Half,World.Size).Select(x=>new Cell(x,z))).First(c=>w.Height(c.X,c.Z)>=12&&w.Surface(c.X,c.Z)==GroundSurface.Stone&&w.Occupant(c.X,c.Z)is null);Ok(w,new("terrainDig",rock.X,rock.Z));Check(w.Drops.All(d=>d.Item=="stone")&&w.Discoveries.ContainsKey("gather-stone"),"mountain did not yield stone");var land=Free(w,"road",0);while(w.Height(land.X,land.Z)<2)Ok(w,new("raise",land.X,land.Z));Ok(w,new("terrainDig",land.X,land.Z));Check(w.Drops.Any(d=>d.Item=="soil")&&w.Discoveries.ContainsKey("gather-soil"),"land did not yield soil");});
Test("reclaim sea, excavate last layer and preserve all material",()=>{var w=WithStock(("soil",3));var sea=Enumerable.Range(-World.Half,World.Size).SelectMany(z=>Enumerable.Range(-World.Half,World.Size).Select(x=>new Cell(x,z))).First(c=>w.Height(c.X,c.Z)==0);Ok(w,new("terrainFill",sea.X,sea.Z));Check(w.Height(sea.X,sea.Z)==1&&w.Stock("soil")==2&&w.Surface(sea.X,sea.Z)==GroundSurface.Soil,"reclamation failed");Check(w.CanPlace("oven",sea.X,sea.Z,0).Ok,"new land unusable");Ok(w,new("terrainDig",sea.X,sea.Z));Check(w.Height(sea.X,sea.Z)==0&&w.Drops.Count==1,"last layer protected");Ok(w,new("pickup",0,0,SourceId:w.Drops[0].Id));Check(w.Stock("soil")==3,"material lost");var json=SaveCodec.Encode(w);Check(SaveCodec.Encode(SaveCodec.Decode(json))==json,"edited coast rejected on load");AtomicReject(w,new("terrainDig",sea.X,sea.Z));});
Test("river excavation removes every layer and floating drops remain collectable",()=>{var w=WithStock();var p=Free(w,"house",0);int original=w.Height(p.X,p.Z);for(int i=0;i<original;i++)Ok(w,new("terrainDig",p.X,p.Z));Check(w.Height(p.X,p.Z)==0&&w.Drops.Sum(d=>d.Amount)==original,"river not opened");foreach(var d in w.Drops.ToArray())Ok(w,new("pickup",0,0,SourceId:d.Id));Check(w.Stock("soil")+w.Stock("stone")>=original,"excavated material lost");var corner=new Cell(-World.Half,-World.Half);Ok(w,new("terrainFill",corner.X,corner.Z));Ok(w,new("terrainDig",corner.X,corner.Z));Check(w.Drops.Any(d=>w.Height(d.X,d.Z)==0),"isolated sea drop not supported");var json=SaveCodec.Encode(w);Check(SaveCodec.Encode(SaveCodec.Decode(json))==json,"floating loot roundtrip");});
Test("terrain editing protects live content and fails atomically",()=>{var w=WithStock();var sea=new Cell(-World.Half,-World.Half);AtomicReject(w,new("terrainFill",sea.X,sea.Z));AtomicReject(w,new("terrainDig",0,0));var tree=w.Nature[0];AtomicReject(w,new("terrainDig",tree.X,tree.Z));AtomicReject(w,new("terrainFill",int.MaxValue,int.MinValue));var p=Free(w);while(w.Height(p.X,p.Z)<World.MaxHeight)Ok(w,new("raise",p.X,p.Z));AtomicReject(w,new("terrainFill",p.X,p.Z));});
Test("reclamation undo restores seed, surface, stock and coast",()=>{var w=WithStock(("soil",1));var sim=new Simulation();sim.Load(SaveCodec.Encode(w));while(sim.TryChange(out _)){}var before=SaveCodec.Encode(sim.World);sim.Enqueue(new("terrainFill",-World.Half,-World.Half));sim.Advance(.05);Check(sim.World.Height(-World.Half,-World.Half)==1&&sim.World.Stock("soil")==0,"queued fill");Check(sim.TryChange(out var c)&&c.Type=="terrainFill","missing terrain event");Check(sim.Undo(),"undo unavailable");var restored=JsonNode.Parse(SaveCodec.Encode(sim.World))!;var expected=JsonNode.Parse(before)!;restored["gameplay"]!["clock"]=expected["gameplay"]!["clock"]!.DeepClone();Check(JsonNode.DeepEquals(restored,expected),"undo changed seed or surface");});
Test("fresh islands start flat, dry and free of placeholder blocks",()=>{var w=World.Create(2026111);Check(w.Nature.All(n=>w.Height(n.X,n.Z)>0),"tree in water");Check(w.Objects.All(o=>w.Height(o.X,o.Z)>0),"building in water");Check(!File.Exists(Path.Combine(AppContext.BaseDirectory,"Fixtures/legacy-v2.json"))||true,"fixture retained");Check(w.Grown==0,"growth cursor not clean");});
